import React from "react";

function ButtonClick() {
  const handleClick = () => {
    alert("Button clicked!");
  };

  return (
    <div>
      <h1>React Button Click Event</h1>
      <button onClick={handleClick}>Click Me!</button>
    </div>
  );
}

export default ButtonClick;
